//autogenerated:yes
//nolint:revive,misspell,govet,lll,dupl,gocritic
package stemstudios

import (
	"github.com/bluenviron/gomavlib/v4/pkg/dialects/common"
)

// Video stream types
type VIDEO_STREAM_TYPE = common.VIDEO_STREAM_TYPE

const (
	// Stream is RTSP
	VIDEO_STREAM_TYPE_RTSP VIDEO_STREAM_TYPE = common.VIDEO_STREAM_TYPE_RTSP
	// Stream is RTP UDP (URI gives the port number)
	VIDEO_STREAM_TYPE_RTPUDP VIDEO_STREAM_TYPE = common.VIDEO_STREAM_TYPE_RTPUDP
	// Stream is MPEG on TCP
	VIDEO_STREAM_TYPE_TCP_MPEG VIDEO_STREAM_TYPE = common.VIDEO_STREAM_TYPE_TCP_MPEG
	// Stream is MPEG TS (URI gives the port number)
	VIDEO_STREAM_TYPE_MPEG_TS VIDEO_STREAM_TYPE = common.VIDEO_STREAM_TYPE_MPEG_TS
	// Stream is WHEP (WebRTC-HTTP Egress Protocol)
	VIDEO_STREAM_TYPE_WHEP VIDEO_STREAM_TYPE = common.VIDEO_STREAM_TYPE_WHEP
	// Stream is SRT (Secure Reliable Transport).
	// The payload is MPEG-TS (as for VIDEO_STREAM_TYPE_MPEG_TS); streams other than video (e.g. KLV metadata, audio) may be ignored.
	// VIDEO_STREAM_INFORMATION.uri is a full URI with the prefix `srt://host:port` followed by query parameters.
	// Recognised parameters include: mode (caller, listener or rendezvous), latency (ms), streamid (opaque string, e.g. for hub access control).
	// Encryption passphrases should be exchanged out of band rather than in the URI, as MAVLink messages are not encrypted.
	VIDEO_STREAM_TYPE_SRT VIDEO_STREAM_TYPE = common.VIDEO_STREAM_TYPE_SRT
)
